CREATE OR REPLACE FUNCTION public.plan_input_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.start_date IS NULL OR NEW.first_due_date IS NULL OR NEW.end_date<NEW.start_date OR NEW.first_due_date<NEW.start_date OR NEW.grace_days NOT BETWEEN 0 AND 60 OR NEW.monthly_fee<0 THEN RAISE EXCEPTION 'Revise as datas, o valor e a tolerância do plano';END IF;RETURN NEW;END $$;
CREATE TRIGGER plan_input_validation BEFORE INSERT OR UPDATE ON public.plans FOR EACH ROW EXECUTE FUNCTION public.plan_input_guard();
CREATE OR REPLACE FUNCTION public.payment_input_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.paid_on>public.today_br() OR NEW.amount<=0 OR length(NEW.method)>100 OR length(coalesce(NEW.notes,''))>4000 THEN RAISE EXCEPTION 'Revise os dados do pagamento';END IF;RETURN NEW;END $$;
CREATE TRIGGER payment_input_validation BEFORE INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.payment_input_guard();
CREATE OR REPLACE FUNCTION public.relationship_daily_notifications() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;elapsed integer;anchor date;planned boolean;BEGIN
FOR r IN SELECT s.id,s.trainer_id,s.user_id,s.created_at,p.full_name,p.birth_date,t.attention_days,t.priority_days,a.available_days,a.submitted_at,(SELECT max(performed_on) FROM public.training_sessions WHERE student_id=s.id AND finished_at IS NOT NULL) last_training FROM public.students s JOIN public.profiles p ON p.id=s.user_id JOIN public.trainer_settings t ON t.trainer_id=s.trainer_id LEFT JOIN public.assessments a ON a.student_id=s.id WHERE s.accompaniment_status NOT IN ('inativo','suspenso') LOOP
IF to_char(r.birth_date,'MM-DD')=to_char(public.today_br(),'MM-DD') AND NOT EXISTS(SELECT 1 FROM public.contact_history WHERE student_id=r.id AND contact_type='aniversario' AND birthday_year=extract(year FROM public.today_br()) AND sent_at IS NOT NULL) THEN PERFORM public.notify(r.trainer_id,'Aniversariante do dia',r.full_name,'/admin/alunos/'||r.id,'birthday_'||r.id||'_'||extract(year FROM public.today_br()));END IF;
anchor:=coalesce(r.last_training,r.submitted_at::date);elapsed:=public.today_br()-anchor;planned:=coalesce(array_length(r.available_days,1),0)=0;
IF NOT planned AND anchor IS NOT NULL THEN SELECT EXISTS(SELECT 1 FROM generate_series(anchor+1,public.today_br(),interval '1 day') d WHERE (ARRAY['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'])[extract(dow FROM d)::int+1]=ANY(r.available_days)) INTO planned;END IF;
IF elapsed>=r.attention_days AND r.submitted_at IS NOT NULL AND planned THEN PERFORM public.notify(r.trainer_id,'Acompanhamento de treino',r.full_name||' está sem registrar treinos. Confira a frequência planejada.','/admin/alunos/'||r.id,'inactivity_'||r.id||'_'||public.today_br());END IF;
END LOOP;
FOR r IN SELECT id,trainer_id,name FROM public.crm_leads WHERE next_contact_on<=public.today_br() AND status NOT IN ('matriculado','nao_convertido') LOOP PERFORM public.notify(r.trainer_id,'Acompanhar interessado',r.name,'/admin/crm','lead_followup_'||r.id||'_'||public.today_br());END LOOP;
END $$;